const row = $input.first().json || {};
const staticData = $getWorkflowStaticData('global');
const isWebhook = Boolean($json.body || $json.query || $json.headers) || Boolean($('Webhook - Run Health Now').isExecuted);
const today = new Date().toISOString().slice(0, 10);
if (!isWebhook && staticData.lastDailySent === today) {
  return [{ json: { send_alert: false, status: 'already_sent_today', date: today } }];
}
const fu = Array.isArray(row.followups_24h) ? row.followups_24h : [];
const stuck = Array.isArray(row.loss_reason_stuck) ? row.loss_reason_stuck : [];
const errs = Array.isArray(row.workflow_errors_24h) ? row.workflow_errors_24h : [];
const lines = ['CRIS OPS-10 — Salud diaria (' + today + ')'];
lines.push('');
lines.push('Followups 24h:');
if (!fu.length) lines.push('  (sin actividad)');
for (const f of fu.slice(0, 12)) lines.push(`  ${f.status} ${f.tipo} x${f.n}` + (f.motivo && f.motivo !== '-' ? ` (${String(f.motivo).slice(0, 40)})` : ''));
lines.push('');
lines.push('LOSS_REASON_PENDING >24h: ' + stuck.length + (stuck.length ? '  <- revisar' : ''));
for (const s of stuck.slice(0, 5)) lines.push(`  ${s.phone} desde ${String(s.updated_at).slice(0, 16)}`);
lines.push('');
lines.push('Errores de workflows 24h: ' + (errs.length ? '' : '0'));
for (const e of errs) lines.push(`  ${e.workflow_name || '?'} x${e.n} (ultimo ${String(e.last_at).slice(0, 16)})`);
const pricing = Array.isArray(row.pricing_events_24h) ? row.pricing_events_24h : [];
lines.push('');
lines.push('Pricing 24h:' + (pricing.length ? '' : ' (sin eventos)'));
for (const p of pricing) lines.push(`  ${p.tipo_evento} x${p.n}` + (p.reason && p.reason !== '-' ? ` (${String(p.reason).slice(0, 50)})` : ''));
const skipped = pricing.filter(p => p.tipo_evento === 'PRICING_SKIPPED').reduce((s, p) => s + Number(p.n || 0), 0);
if (skipped > 0) lines.push('  <- revisar PRICING_SKIPPED: posible menu no entregado');
const regressions = Array.isArray(row.post_pricing_state_regressions_24h) ? row.post_pricing_state_regressions_24h : [];
lines.push('');
lines.push('Regresiones post-cotizacion 24h: ' + regressions.length + (regressions.length ? '  <- revisar' : ''));
for (const r of regressions.slice(0, 10)) {
  lines.push('  ' + String(r.conversation_id || '?').slice(0, 8) + ' -> ' + (r.new_state || '?')
    + ' (' + String(r.created_at || '').slice(0, 16) + ')');
}
if (!isWebhook) staticData.lastDailySent = today;
return [{ json: {
  send_alert: true,
  source: isWebhook ? 'manual' : 'schedule',
  date: today,
  followups_24h: fu,
  loss_reason_stuck: stuck,
  workflow_errors_24h: errs,
  post_pricing_state_regressions_24h: regressions,
  meta_payload: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: '5521999910781',
    type: 'text',
    text: { preview_url: false, body: lines.join('\n').slice(0, 3900) },
  },
} }];

const resp = $json || {};
const status = resp.statusCode || resp.status || null;
return [{ json: { status: 'summary_sent', http_status: status, date: $('Code - Build Health Summary').first().json.date } }];
